ALTER TABLE category_groups ADD COLUMN kind TEXT;
ALTER TABLE categories ADD COLUMN kind TEXT;
ALTER TABLE categories ADD COLUMN account_id TEXT;
CREATE UNIQUE INDEX category_groups_payment_kind ON category_groups (budget_id) WHERE kind IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX categories_payment_account ON categories (account_id) WHERE account_id IS NOT NULL AND deleted_at IS NULL;
INSERT INTO category_groups (id, budget_id, name, sort_order, hidden, collapsed, created_at, updated_at, deleted_at, kind) SELECT lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6))), b.budget_id, 'Credit Card Payments', coalesce((SELECT min(g.sort_order) FROM category_groups g WHERE g.budget_id = b.budget_id AND g.deleted_at IS NULL), 1) - 1, 0, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'credit_card_payments' FROM (SELECT DISTINCT a.budget_id AS budget_id FROM accounts a WHERE a.type IN ('creditCard','lineOfCredit') AND a.deleted_at IS NULL) b WHERE NOT EXISTS (SELECT 1 FROM category_groups g WHERE g.budget_id = b.budget_id AND g.kind = 'credit_card_payments' AND g.deleted_at IS NULL);
INSERT INTO categories (id, budget_id, group_id, name, sort_order, hidden, created_at, updated_at, deleted_at, note, kind, account_id) SELECT lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6))), a.budget_id, g.id, a.name, coalesce((SELECT max(c.sort_order) FROM categories c WHERE c.group_id = g.id AND c.deleted_at IS NULL), -1) + row_number() OVER (PARTITION BY a.budget_id ORDER BY a.sort_order, a.id), 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, NULL, 'credit_card_payment', a.id FROM accounts a JOIN category_groups g ON g.budget_id = a.budget_id AND g.kind = 'credit_card_payments' AND g.deleted_at IS NULL WHERE a.type IN ('creditCard','lineOfCredit') AND a.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM categories c WHERE c.account_id = a.id AND c.deleted_at IS NULL);
